///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_GoURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GoURL = async function () {
    const sbmOptions = {
        id: "tx_fn_GoURL",
        method: "post",
        action: "/support/dsclData.do",
        ref: "dma_GoURLReq",
        target: "dlt_dsclDataBbsAttachVO=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil15901.tx_fn_GoURL" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/fileDownload.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param flag contnId
 * @returns
 * @hidden N
*/
scwin.goURL = async function (flag, contnId) {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (flag === 'list') {
        $c.util.getComponent('dma_GoURLReq').set('method', 'searchDsclData');
        (document.dsclDataForm || { elements: [] }).action = 'dsclData.do';
        { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15900/jldfil15900.xml", { "method": 'searchDsclData', "contnId": contnId }); } };
    } else {
        if (flag === 'detail') {
            $c.util.getComponent('dma_GoURLReq').set('method', 'searchDsclDataDetail');
            $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
            (document.dsclDataForm || { elements: [] }).action = 'dsclData.do';
            { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15900/jldfil15900.xml", { "method": 'searchDsclData', "contnId": contnId }); } };
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId attachSeq attachFileNm wrtDdtm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, attachSeq, attachFileNm, wrtDdtm) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_GoURLReq').set('method', 'searchBbsAttachFile');
    $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
    $c.util.getComponent('dma_GoURLReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_GoURLReq').set('attachFileNm', attachFileNm);
    $c.util.getComponent('dma_GoURLReq').set('wrtDdtm', wrtDdtm);
    (document.dsclDataForm || { elements: [] }).action = '/support/fileDownload.do';
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};
